import React from "react";
import ProductRow from "./ProductRow";

export default function StorageTransfer({
  block,
  blockIdx,
  categories,
  storages,
  onRemoveBlock,
  onAddProductRow,
  onRemoveProductRow,
  onUpdateBlockField,
  onUpdateProductField
}) {
  return (
    <div className="storage-transfer-section">
      <div className="section-header">
        <h3>Storage Transfer Block {blockIdx + 1}</h3>
        <p className="section-description">
          Relocate products to a specific destination storage
        </p>
      </div>

      <div className="transfer-block">
        {/* Destination Storage Selection */}
        <div className="transfer-header">
          <div className="transfer-cell">
            <select
              className="input storage-input"
              value={block.destinationStorage}
              onChange={(e) => onUpdateBlockField("destinationStorage", e.target.value)}
            >
              <option value="">Select Destination Storage</option>
              {storages.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.name}
                </option>
              ))}
            </select>
          </div>
          <div className="remove-transfer-cell">
            <button className="btn remove-transfer-btn" onClick={onRemoveBlock}>×</button>
          </div>
        </div>

        {/* Product Rows */}
        <div className="product-rows">
          {block.productRows.map((product, index) => (
            <ProductRow
              key={product.id}
              pr={product}
              categories={categories}
              storages={storages}
              onChange={(field, value) => onUpdateProductField(index, field, value)}
              onRemove={() => onRemoveProductRow(index)}
            />
          ))}
        </div>

        {/* Add Product Row Button */}
        <div className="add-product-row">
          <button className="btn add-product-btn" onClick={onAddProductRow}>
            + Add Product
          </button>
        </div>
      </div>
    </div>
  );
}
